<main class="section"><div class="section-head"><div><span class="eyebrow">Arbeitszentrale</span><h1>Admin Dashboard</h1></div><form method="post" action="/admin/logout"><?=App\Core\Csrf::field()?><button class="btn ghost">Abmelden</button></form></div><div class="dash-grid"><?php $labels=['prechecks'=>'Vorabkontrollen','evidence'=>'Nachweise','violations'=>'Verstöße','damage'=>'Beschädigungen','revisions'=>'Revisionen','payouts'=>'Auszahlungen'];foreach($labels as $k=>$label):?><div class="card dash-card"><span><?=App\Core\View::e($label)?></span><strong><?= (int)$counts[$k] ?></strong><small>offen / zu prüfen</small></div><?php endforeach;?></div><div class="admin-nav"><a class="btn primary" href="/admin/entscheidungen">Entscheidungen</a><a class="btn" href="/admin/fristen">Fristen</a><a class="btn" href="/admin/kalender">Kalender</a><a class="btn" href="/admin/suche">Suche</a><a class="btn" href="/admin/verkaeuferinnen">Verkäuferinnen</a><a class="btn" href="/admin/kategorien">Kategorien</a><a class="btn" href="/admin/angebote">Angebote</a><a class="btn" href="/admin/aufgaben">Aufgaben</a><a class="btn" href="/admin/auszahlungen">Auszahlungen</a><a class="btn" href="/admin/empfaengeradressen">Empfängeradressen</a><a class="btn" href="/admin/archiv">Archiv</a><a class="btn ghost" href="/admin/einstellungen">Einstellungen</a><a class="btn ghost" href="/admin/system/update">Systemupdate</a></div><section class="worklist"><h2>Heute & nächste 24 Stunden</h2><?php foreach($due as $d):?><div class="work-row"><div><b><?=App\Core\View::e($d['title'])?></b><span><?=App\Core\View::e($d['event_type'])?> · <?=date('d.m.Y H:i',strtotime($d['starts_at']))?></span></div><?php if($d['order_id']):?><span>#<?= (int)$d['order_id'] ?></span><?php endif;?></div><?php endforeach;?><?php if(!$due):?><div class="empty">Keine anstehenden Kalenderereignisse.</div><?php endif;?></section></main>